// Fake `codex app-server` for adapter tests: JSON-RPC 2.0, one JSON object per line,
// speaking the v2 shapes generated by `codex app-server generate-ts` (codex-cli 0.166.0).
// The user text of turn/start picks the scenario:
//   "hello ..."      -> streams an agent message in deltas
//   "approve-cmd"    -> asks item/commandExecution/requestApproval, reports the decision
//   "approve-file"   -> asks item/fileChange/requestApproval, then completes a fileChange
//   "approve-perm"   -> asks item/permissions/requestApproval
//   "approve-legacy" -> asks execCommandApproval (legacy shape)
//   "unknown-req"    -> sends an unsupported server request (item/tool/call)
//   "run"            -> completes read / search / run commandExecution items
//   "malformed"      -> writes a garbage line, then streams normally
//   "crash"          -> exits with code 3 mid-turn
// `fake/log` returns every message received so far (tests inspect the requests).
import readline from 'node:readline';

const received = [];
let nextServerReqId = 1000;
const waiting = new Map(); // server request id -> resolve
let turnN = 0;
let threadN = 0;
let steerWaiter = null; // resolve(text) for the "wait-steer" scenario

const send = (msg) => process.stdout.write(JSON.stringify(msg) + '\n');
const notify = (method, params) => send({ jsonrpc: '2.0', method, params });
const ask = (method, params) => new Promise((resolve) => {
  const id = nextServerReqId++;
  waiting.set(id, resolve);
  send({ jsonrpc: '2.0', id, method, params });
});

const thread = (id, cwd, extra = {}) => ({
  id, sessionId: id, forkedFromId: null, parentThreadId: null, preview: 'first message', ephemeral: false,
  section: null, sectionEnteredAt: null, projectId: null, historyMode: 'full', modelProvider: 'openai',
  model: null, reasoningEffort: null, createdAt: 1761000000, updatedAt: 1761000100, recencyAt: null,
  status: { type: 'idle' }, path: null, cwd, cliVersion: '0.166.0', originator: null, source: 'appServer',
  threadSource: null, agentNickname: null, agentRole: null, gitInfo: null, name: null, turns: [], ...extra,
});

const HISTORY = [{
  id: 'turn-old', rootTurnId: null, itemsView: 'full', status: 'completed', error: null,
  startedAt: 1, completedAt: 2, durationMs: 1,
  items: [
    { type: 'userMessage', id: 'u1', clientId: null, content: [{ type: 'text', text: 'old question', text_elements: [] }] },
    { type: 'reasoning', id: 'r1', summary: [], content: [] },
    { type: 'commandExecution', id: 'c1', pluginId: null, scriptPath: null, command: 'npm test', cwd: 'C:\\proj',
      processId: null, source: 'agent', status: 'completed', commandActions: [{ type: 'unknown', command: 'npm test' }],
      aggregatedOutput: 'ok', exitCode: 0, durationMs: 5 },
    { type: 'agentMessage', id: 'a1', text: 'old answer', phase: null, memoryCitation: null, delivery: null, questions: null },
  ],
}];

const LIST = [
  thread('t-a', 'C:\\Proj\\A', { name: 'TestraTech', updatedAt: 1761000300 }),
  thread('t-b', '\\\\?\\c:\\proj\\a\\', { name: null, preview: 'preview title' }),
  thread('t-c', 'C:\\Proj\\Other', { name: 'Other' }),
];

const cmdItem = (id, command, actions, status, exitCode) => ({
  type: 'commandExecution', id, pluginId: null, scriptPath: null, command, cwd: 'C:\\proj', processId: null,
  source: 'agent', status, commandActions: actions, aggregatedOutput: null, exitCode, durationMs: 1,
});

async function runTurn(threadId, turnId, text) {
  const base = { threadId, turnId };
  const turn = (status) => ({ id: turnId, rootTurnId: null, items: [], itemsView: 'notLoaded', status,
    error: null, startedAt: 1, completedAt: status === 'inProgress' ? null : 2, durationMs: null });
  notify('turn/started', { threadId, turn: turn('inProgress') });
  // like the real server: the user's own message comes back as an item
  const userItem = { type: 'userMessage', id: 'u-' + turnId, clientId: null, content: [{ type: 'text', text, text_elements: [] }] };
  notify('item/started', { ...base, item: userItem, startedAtMs: 1 });
  notify('item/completed', { ...base, item: userItem, completedAtMs: 1 });
  const message = async (id, parts) => {
    notify('item/started', { ...base, item: { type: 'agentMessage', id, text: '', phase: null, memoryCitation: null, delivery: null, questions: null }, startedAtMs: 1 });
    for (const p of parts) notify('item/agentMessage/delta', { ...base, itemId: id, delta: p });
    notify('item/completed', { ...base, item: { type: 'agentMessage', id, text: parts.join(''), phase: null, memoryCitation: null, delivery: null, questions: null }, completedAtMs: 2 });
  };
  if (text === 'crash') {
    notify('item/agentMessage/delta', { ...base, itemId: 'm-crash', delta: 'partial' });
    setTimeout(() => process.exit(3), 20);
    return;
  }
  if (text === 'wait-steer') {
    notify('item/started', { ...base, item: { type: 'agentMessage', id: 'm-steer', text: '', phase: null, memoryCitation: null, delivery: null, questions: null }, startedAtMs: 1 });
    notify('item/agentMessage/delta', { ...base, itemId: 'm-steer', delta: 'waiting…' });
    const steered = await new Promise(r => { steerWaiter = r; });
    notify('item/agentMessage/delta', { ...base, itemId: 'm-steer', delta: 'steered=' + steered });
    notify('item/completed', { ...base, item: { type: 'agentMessage', id: 'm-steer', text: 'waiting…steered=' + steered, phase: null, memoryCitation: null, delivery: null, questions: null }, completedAtMs: 2 });
    notify('turn/completed', { threadId, turn: turn('completed') });
    return;
  }
  if (text === 'malformed') process.stdout.write('this is {not json\n');
  if (text === 'approve-cmd') {
    const r = await ask('item/commandExecution/requestApproval', {
      kind: 'command', ...base, itemId: 'cmd-1', startedAtMs: 1, environmentId: null,
      reason: 'needs network', command: 'npm install', cwd: 'C:\\proj',
    });
    await message('m-dec', ['decision=' + JSON.stringify(r.result ?? r.error)]);
  } else if (text === 'approve-file') {
    const r = await ask('item/fileChange/requestApproval', { ...base, itemId: 'fc-1', startedAtMs: 1, reason: 'edit', grantRoot: null });
    notify('item/completed', { ...base, completedAtMs: 2, item: { type: 'fileChange', id: 'fc-1', status: 'completed', changes: [
      { path: 'C:\\proj\\a.txt', kind: { type: 'update', move_path: null }, diff: '--- a\n+++ b\n@@ -1 +1,2 @@\n-x\n+y\n+z\n' },
      { path: 'C:\\proj\\new.txt', kind: { type: 'add' }, diff: 'line1\nline2\n' },
    ] } });
    await message('m-dec', ['decision=' + JSON.stringify(r.result ?? r.error)]);
  } else if (text === 'approve-perm') {
    const r = await ask('item/permissions/requestApproval', {
      ...base, itemId: 'p-1', environmentId: null, startedAtMs: 1, cwd: 'C:\\proj', reason: 'network',
      permissions: { network: { enabled: true }, fileSystem: null },
    });
    await message('m-dec', ['decision=' + JSON.stringify(r.result ?? r.error)]);
  } else if (text === 'approve-perm-fs') {
    const r = await ask('item/permissions/requestApproval', {
      ...base, itemId: 'p-2', environmentId: null, startedAtMs: 1, cwd: 'C:/proj', reason: 'fs',
      permissions: {
        network: { enabled: true, extra: 'not shown' },
        fileSystem: { read: ['C:/a'], write: null, globScanMaxDepth: 9, entries: [{ path: 'C:/', access: 'write' }] },
      },
    });
    await message('m-dec', ['decision=' + JSON.stringify(r.result ?? r.error)]);
  } else if (text === 'approve-resolved') {
    // the server stops waiting on its own (e.g. the turn moved on) and says so
    const id = nextServerReqId++;
    waiting.set(id, () => {});
    send({ jsonrpc: '2.0', id, method: 'item/commandExecution/requestApproval', params: {
      kind: 'command', ...base, itemId: 'cmd-r', startedAtMs: 1, environmentId: null, reason: null, command: 'ls', cwd: 'C:/proj' } });
    await new Promise(r => setTimeout(r, 80));
    notify('serverRequest/resolved', { threadId, requestId: id });
    await new Promise(r => setTimeout(r, 80));
    await message('m-after', ['after']);
  } else if (text === 'approve-legacy') {
    const r = await ask('execCommandApproval', {
      conversationId: threadId, callId: 'call-1', approvalId: null, command: ['git', 'push'], cwd: 'C:\\proj', reason: null, parsedCmd: [],
    });
    await message('m-dec', ['decision=' + JSON.stringify(r.result ?? r.error)]);
  } else if (text === 'unknown-req') {
    const r = await ask('item/tool/call', { threadId, turnId, callId: 'x', tool: 'nope', arguments: {} });
    await message('m-dec', ['unknown=' + JSON.stringify(r.error ? { error: r.error.code } : r.result)]);
  } else if (text === 'run') {
    const items = [
      cmdItem('c-read', 'cat a.txt', [{ type: 'read', command: 'cat a.txt', name: 'a.txt', path: 'C:\\proj\\a.txt' }], 'completed', 0),
      cmdItem('c-search', 'rg foo', [{ type: 'search', command: 'rg foo', query: 'foo', path: null }], 'completed', 0),
      cmdItem('c-run', 'npm test', [{ type: 'unknown', command: 'npm test' }], 'failed', 1),
    ];
    for (const item of items) {
      notify('item/started', { ...base, item: { ...item, status: 'inProgress', exitCode: null }, startedAtMs: 1 });
      notify('item/completed', { ...base, item, completedAtMs: 2 });
    }
  } else {
    await message('m-' + turnId, ['Hel', 'lo ', 'there']);
  }
  notify('turn/completed', { threadId, turn: turn('completed') });
}

const rl = readline.createInterface({ input: process.stdin });
rl.on('line', (line) => {
  const msg = JSON.parse(line);
  received.push(msg);
  if (msg.id !== undefined && !msg.method) { // response to one of our server requests
    const resolve = waiting.get(msg.id);
    waiting.delete(msg.id);
    resolve?.(msg);
    return;
  }
  if (msg.id === undefined) return; // client notification (initialized)
  const reply = (result) => send({ jsonrpc: '2.0', id: msg.id, result });
  const p = msg.params ?? {};
  switch (msg.method) {
    case 'initialize':
      return reply({ userAgent: 'fake/0.166.0', codexHome: process.env.CODEX_HOME ?? 'C:\\fake', platformFamily: 'windows', platformOs: 'windows' });
    case 'thread/start': {
      const t = thread('thread-' + (++threadN), p.cwd);
      return reply({ thread: t, model: 'gpt', modelProvider: 'openai', serviceTier: null, disabledPluginIds: [], cwd: p.cwd,
        instructionSources: [], approvalPolicy: p.approvalPolicy, approvalsReviewer: 'user', sandbox: { type: p.sandbox }, reasoningEffort: null });
    }
    case 'thread/resume': {
      const t = thread(p.threadId, 'C:\\proj', { turns: HISTORY });
      return reply({ thread: t, model: 'gpt', modelProvider: 'openai', serviceTier: null, disabledPluginIds: [], cwd: 'C:\\proj',
        instructionSources: [], approvalPolicy: 'on-request', approvalsReviewer: 'user', sandbox: { type: 'readOnly' },
        reasoningEffort: null, collaborationMode: null, turnsBackwardsCursor: null, itemsBackwardsCursor: null });
    }
    case 'thread/read':
      return reply({ thread: thread(p.threadId, 'C:\\proj', { turns: p.includeTurns ? HISTORY : [] }) });
    case 'thread/list':
      return reply({ data: LIST, nextCursor: null, backwardsCursor: null });
    case 'turn/start': {
      const turnId = 'turn-' + (++turnN);
      reply({ turn: { id: turnId, rootTurnId: null, items: [], itemsView: 'notLoaded', status: 'inProgress', error: null, startedAt: 1, completedAt: null, durationMs: null } });
      runTurn(p.threadId, turnId, p.input?.[0]?.text ?? '');
      return;
    }
    case 'turn/steer': {
      if (!steerWaiter || p.expectedTurnId !== 'turn-' + turnN) {
        return send({ jsonrpc: '2.0', id: msg.id, error: { code: -32600, message: 'no active turn' } });
      }
      reply({ turnId: p.expectedTurnId });
      const w = steerWaiter; steerWaiter = null;
      w(p.input?.[0]?.text ?? '');
      return;
    }
    case 'turn/interrupt':
      reply({});
      notify('turn/completed', { threadId: p.threadId, turn: { id: p.turnId, rootTurnId: null, items: [], itemsView: 'notLoaded', status: 'interrupted', error: null, startedAt: 1, completedAt: 2, durationMs: null } });
      return;
    case 'fake/hang':
      return;
    case 'fake/log':
      return reply({ received, pid: process.pid, env: { CODEX_HOME: process.env.CODEX_HOME ?? null, OPENAI_API_KEY: process.env.OPENAI_API_KEY ?? null } });
    default:
      send({ jsonrpc: '2.0', id: msg.id, error: { code: -32601, message: 'unknown method ' + msg.method } });
  }
});
